window.SOLITON_DATA={frames:271,n:384,xmin:-30.0000,xmax:29.8438,tmax:54,peak:1.4999,b64:""};
// Two solitons of a coupled nonlinear Schrodinger system collide and bounce apart.
// The frames were computed offline with a split-step Fourier method (soliton-data.js).
// Top panel: the density of each component at the current time.
// Bottom panel: the space-time history, drawn up to the current time.
(function () {
  "use strict";

  var D = window.SOLITON_DATA;
  var canvas = document.getElementById("soliton-canvas");
  if (!D || !canvas || !canvas.getContext) return;
  var ctx = canvas.getContext("2d");
  var button = document.getElementById("soliton-play");

  var css = getComputedStyle(document.documentElement);
  var COLORS = [
    (css.getPropertyValue("--violet") || "#6a3d9a").trim(),
    (css.getPropertyValue("--teal") || "#1c7a80").trim()
  ];
  var MUTED = (css.getPropertyValue("--muted") || "#5a6475").trim();
  var RULE = (css.getPropertyValue("--rule") || "#dce1e8").trim();
  var SANS = (css.getPropertyValue("--sans") || "sans-serif").trim();
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // decode frames: [frame][component][point], uint8 scaled to D.peak
  var raw = atob(D.b64), bytes = new Uint8Array(raw.length);
  for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  var NF = D.frames, NX = D.n;
  function val(f, c, j) { return bytes[(f * 2 + c) * NX + j] / 255; }

  // space-time image, one row per frame, time increasing upward
  var st = document.createElement("canvas");
  st.width = NX; st.height = NF;
  (function () {
    var sctx = st.getContext("2d"), img = sctx.createImageData(NX, NF);
    var c0 = hex(COLORS[0]), c1 = hex(COLORS[1]);
    for (var f = 0; f < NF; f++) {
      var row = NF - 1 - f;
      for (var j = 0; j < NX; j++) {
        var a = Math.min(1, val(f, 0, j) * 1.4), b = Math.min(1, val(f, 1, j) * 1.4);
        var k = (row * NX + j) * 4, al = Math.min(1, a + b), s = a + b || 1;
        img.data[k]     = (a * c0[0] + b * c1[0]) / s;
        img.data[k + 1] = (a * c0[1] + b * c1[1]) / s;
        img.data[k + 2] = (a * c0[2] + b * c1[2]) / s;
        img.data[k + 3] = 255 * al;
      }
    }
    sctx.putImageData(img, 0, 0);
  })();

  function hex(h) {
    h = h.replace("#", "");
    if (h.length === 3) h = h.replace(/./g, "$&$&");
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }

  var W = 0, H = 0;
  function resize() {
    var r = canvas.getBoundingClientRect(), dpr = window.devicePixelRatio || 1;
    W = r.width; H = r.height;
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function draw(t) {                               // t in [0, NF - 1], may be fractional
    ctx.clearRect(0, 0, W, H);
    var left = 44, right = W - 12, top = 10;
    var waveBase = Math.round(H * 0.36), stTop = waveBase + 18, stBot = H - 34;
    var pw = right - left, f0 = Math.floor(t), f1 = Math.min(NF - 1, f0 + 1), w = t - f0;
    function X(j) { return left + pw * j / (NX - 1); }
    function xToPx(x) { return left + pw * (x - D.xmin) / (D.xmax - D.xmin); }

    // waves
    var amp = waveBase - top - 4;
    for (var c = 0; c < 2; c++) {
      ctx.beginPath();
      for (var j = 0; j < NX; j++) {
        var v = (1 - w) * val(f0, c, j) + w * val(f1, c, j);
        if (j) ctx.lineTo(X(j), waveBase - amp * v); else ctx.moveTo(X(j), waveBase - amp * v);
      }
      ctx.strokeStyle = COLORS[c]; ctx.lineWidth = 2; ctx.stroke();
      ctx.lineTo(X(NX - 1), waveBase); ctx.lineTo(X(0), waveBase); ctx.closePath();
      ctx.globalAlpha = 0.18; ctx.fillStyle = COLORS[c]; ctx.fill(); ctx.globalAlpha = 1;
    }

    ctx.strokeStyle = "#c3cad5"; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(left, waveBase); ctx.lineTo(right, waveBase); ctx.stroke();

    // space-time history up to time t
    var ph = stBot - stTop, frac = t / (NF - 1), yNow = stBot - ph * frac;
    ctx.strokeStyle = RULE; ctx.lineWidth = 1;
    ctx.strokeRect(left + 0.5, stTop + 0.5, pw - 1, ph - 1);
    ctx.save();
    ctx.beginPath(); ctx.rect(left, yNow, pw, stBot - yNow); ctx.clip();
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(st, left, stTop, pw, ph);
    ctx.restore();
    ctx.strokeStyle = MUTED; ctx.setLineDash([3, 3]);
    ctx.beginPath(); ctx.moveTo(left, Math.round(yNow) + 0.5); ctx.lineTo(right, Math.round(yNow) + 0.5); ctx.stroke();
    ctx.setLineDash([]);

    // labels
    ctx.fillStyle = MUTED; ctx.font = "12px " + SANS; ctx.textAlign = "center"; ctx.textBaseline = "top";
    for (var xt = -20; xt <= 20; xt += 10) ctx.fillText(xt === 0 ? "0" : String(xt).replace("-", "−"), xToPx(xt), stBot + 6);
    ctx.fillText("Position", left + pw / 2, stBot + 20 - 2);
    ctx.textAlign = "left"; ctx.textBaseline = "bottom";
    ctx.fillText("t = " + (frac * D.tmax).toFixed(0), left + 6, Math.max(stTop + 16, yNow - 3));
    ctx.save(); ctx.translate(22, (stTop + stBot) / 2); ctx.rotate(-Math.PI / 2);
    ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText("Time \u2192", 0, 0); ctx.restore();
  }

  // playback: about 9 s per run, a short hold at the end, then repeat
  var RUN = 9000, HOLD = 1600, elapsed = 0, last = null, playing = false, visible = true, raf = 0, t = 0;
  function frame(now) {
    if (last !== null) elapsed += Math.min(100, now - last);
    last = now;
    if (elapsed > RUN + HOLD) elapsed = 0;
    t = Math.min(1, elapsed / RUN) * (NF - 1);
    draw(t);
    raf = playing && visible ? requestAnimationFrame(frame) : 0;
  }
  function kick() { if (!raf && playing && visible) { last = null; raf = requestAnimationFrame(frame); } }
  function play() {
    if (t >= NF - 1) elapsed = 0;
    playing = true; setButton(); kick();
  }
  function pause() { playing = false; setButton(); }
  function setButton() {
    if (!button) return;
    button.textContent = playing ? "Pause" : "Play";
  }
  if (button) button.addEventListener("click", function () { playing ? pause() : play(); });

  resize();
  if (reduce) { t = NF - 1; draw(t); setButton(); }
  else play();

  window.addEventListener("resize", function () { resize(); draw(t); });
  if ("IntersectionObserver" in window) {
    new IntersectionObserver(function (entries) {
      visible = entries[0].isIntersecting;
      kick();
    }).observe(canvas);
  }
})();
